package com.keplerslicer.app;

import android.content.Context;
import android.content.SharedPreferences;
import org.json.JSONArray;
import org.json.JSONException;
import org.json.JSONObject;
import com.keplerslicer.app.settings.PresetRepository;
import com.keplerslicer.app.settings.PresetJson;
import java.io.File;
import java.io.IOException;
import java.net.URI;
import java.nio.charset.StandardCharsets;
import java.util.LinkedHashMap;
import java.util.Map;
import java.util.concurrent.atomic.AtomicBoolean;

/** Preferences with real consumers. All network/disk actions are worker-only unless stated. */
public final class OnlinePreferences {
    public static final String[] REGIONS={"Asia-Pacific","China","Europe","North America","Others"};
    public static final String[] LOG_LEVELS={"fatal","error","warning","info","debug","trace"};
    private static final String TOKEN=StorageNames.CLOUD_TOKEN;
    private static final Object SESSION_LOCK=new Object(),REFRESH_LOCK=new Object(),SYNC_LOCK=new Object();
    private static final AtomicBoolean RUNNING=new AtomicBoolean();
    private static volatile long lastForegroundAttempt;
    private static volatile NetworkHttp.Cancellation automaticRequest;
    private OnlinePreferences(){}
    private static SharedPreferences prefs(Context c){return c.getSharedPreferences("app_preferences",0);}
    public static void attach(Context c){NetworkPolicy.install(c);}
    public static void changed(Context c){attach(c);if(NetworkPolicy.offline(c)||prefs(c).getBoolean("stealth_mode",false))NetworkHttp.cancelActive();NetworkHttp.Cancellation automatic=automaticRequest;if(!prefs(c).getBoolean("sync_user_preset",false)&&automatic!=null)automatic.cancel();lastForegroundAttempt=0;foreground(c);}
    /** No network work is started unless the user explicitly enabled a network preference. */
    public static void foreground(Context context){Context c=context.getApplicationContext();attach(c);SharedPreferences p=prefs(c);if(NetworkPolicy.offline(c)||p.getBoolean("stealth_mode",false)||!p.getBoolean("sync_user_preset",false))return;long now=android.os.SystemClock.elapsedRealtime();if(lastForegroundAttempt!=0&&now-lastForegroundAttempt<300000)return;if(!RUNNING.compareAndSet(false,true))return;lastForegroundAttempt=now;new Thread(()->{try{if(prefs(c).getBoolean("sync_user_preset",false)&&session(c)!=null)synchronize(c,true);}catch(Exception e){record(c,2,"background-sync",e.getClass().getSimpleName());prefs(c).edit().putString("online_last_error",safeMessage(e)).apply();}finally{RUNNING.set(false);}},"kepler-preferences-sync").start();}
    public static int regionIndex(Context c){String value=prefs(c).getString("region",REGIONS[0]);for(int i=0;i<REGIONS.length;i++)if(REGIONS[i].equals(value))return i;return 0;}
    /** Bambu-specific region routing cannot be applied without the absent Android provider. */
    /** Region of the Bambu Lab account (China uses bambulab.cn, every other region bambulab.com). */
    public static void setRegion(Context c,int index)throws IOException{if(index<0||index>=REGIONS.length)throw new IOException("Unknown region");if(!prefs(c).edit().putString("region",REGIONS[index]).commit())throw new IOException(L.t("Не удалось сохранить регион."));}
    public static String region(Context c){return REGIONS[regionIndex(c)];}
    public static void setStealth(Context c,boolean enabled)throws IOException{if(!prefs(c).edit().putBoolean("stealth_mode",enabled).commit())throw new IOException(L.t("Режим не сохранён."));changed(c);}
    public static JSONObject session(Context c)throws IOException{synchronized(SESSION_LOCK){try{String raw=NetworkSecrets.get(c,TOKEN);return raw.isEmpty()?null:new JSONObject(raw);}catch(JSONException e){throw new IOException(L.t("Сессия облака профилей повреждена."),e);}}}
    public static void saveSession(Context c,JSONObject data)throws IOException{synchronized(SESSION_LOCK){try{if(data.optString("access_token").isEmpty()||data.optString("refresh_token").isEmpty()||data.optJSONObject("user")==null)throw new IOException(L.t("Неполная сессия."));if(data.optLong("expires_at",0)==0)data.put("expires_at",System.currentTimeMillis()/1000+data.optLong("expires_in",0));NetworkPolicy.requireCloud(c);NetworkSecrets.put(c,TOKEN,data.toString());}catch(JSONException e){throw new IOException(e);}}}
    public static void logout(Context c)throws IOException{synchronized(SESSION_LOCK){NetworkSecrets.remove(c,TOKEN);}}
    public static CloudProfileSync.Response tokenRequest(Context c,String path,String body)throws IOException{NetworkPolicy.requireCloud(c);Map<String,String> headers=new LinkedHashMap<>();headers.put("apikey",CloudProfileOAuth.PUBLISHABLE_KEY);headers.put("Content-Type","application/json");NetworkHttp.Response r=NetworkHttp.request("POST",URI.create(CloudProfileOAuth.AUTH_BASE+"/"+path),headers,NetworkHttp.bytes(body.getBytes(StandardCharsets.UTF_8)),new NetworkHttp.Cancellation());return new CloudProfileSync.Response(r.status,r.text());}
    public static JSONObject freshSession(Context c)throws IOException{synchronized(REFRESH_LOCK){
        NetworkPolicy.requireCloud(c);JSONObject current=session(c);if(current==null)throw new IOException(L.t("Сначала войдите в облако профилей."));if(current.optLong("expires_at",0)>System.currentTimeMillis()/1000+60)return current;
        try{String refresh=current.optString("refresh_token");if(refresh.isEmpty())throw new IOException(L.t("Нет токена обновления."));CloudProfileSync.Response r=tokenRequest(c,"auth/v1/token?grant_type=refresh_token",new JSONObject().put("refresh_token",refresh).toString());if(r.status<200||r.status>=300)throw new IOException(L.t("Обновление входа: HTTP ")+r.status);JSONObject next=new JSONObject(r.body);if(next.optJSONObject("user")==null)next.put("user",current.getJSONObject("user"));
            synchronized(SESSION_LOCK){JSONObject active=session(c);if(active==null||!active.optString("access_token").equals(current.optString("access_token")))throw new IOException(L.t("Сессия изменилась во время обновления."));saveSession(c,next);}return next;
        }catch(JSONException e){throw new IOException(L.t("Неверный ответ входа."),e);}
    }}
    public static CloudProfileSync client(Context c,JSONObject session){return cloud(c,session,false);}
    private static CloudProfileSync cloud(Context c,JSONObject session,boolean automatic){String token=session.optString("access_token");return new CloudProfileSync((method,path,body)->{NetworkPolicy.requireCloud(c);if(automatic&&!prefs(c).getBoolean("sync_user_preset",false))throw new IOException(L.t("Автосинхронизация отключена."));JSONObject active=session(c);if(active==null||!active.optString("access_token").equals(token))throw new IOException(L.t("Сессия изменилась во время синхронизации."));Map<String,String> h=new LinkedHashMap<>();h.put("Authorization","Bearer "+token);if(body!=null)h.put("Content-Type","application/json");NetworkHttp.Cancellation tokenRequest=new NetworkHttp.Cancellation();if(automatic)automaticRequest=tokenRequest;try{if(automatic&&!prefs(c).getBoolean("sync_user_preset",false))throw new IOException(L.t("Автосинхронизация отключена."));NetworkHttp.Response r=NetworkHttp.request(method,URI.create("https://api.orcaslicer.com/"+path),h,body==null?null:NetworkHttp.bytes(body.getBytes(StandardCharsets.UTF_8)),tokenRequest,32*1024*1024);return new CloudProfileSync.Response(r.status,r.text());}finally{if(automatic&&automaticRequest==tokenRequest)automaticRequest=null;}});}
    /** Pulls and merges into the real preset repository before pushing locally changed profiles. */
    public static String syncNow(Context c)throws IOException{return synchronize(c,false);}
    private static String synchronize(Context c,boolean automatic)throws IOException{synchronized(SYNC_LOCK){NetworkPolicy.requireCloud(c);if(automatic&&!prefs(c).getBoolean("sync_user_preset",false))throw new IOException(L.t("Автосинхронизация отключена."));JSONObject s=freshSession(c),user=s.optJSONObject("user");if(user==null||user.optString("id").isEmpty())throw new IOException(L.t("Нет идентификатора аккаунта."));String account=user.optString("id");CloudProfileSync api=cloud(c,s,automatic);CloudProfileStore mirror=new CloudProfileStore(c,account);int uploaded=0,deleted=0,applied;
        try(PresetRepository repo=new PresetRepository(c)){JSONArray removals=repo.cloudDeletes(account);for(int i=0;i<removals.length();i++){JSONObject row=removals.optJSONObject(i);if(row==null)throw new IOException(L.t("Неверная очередь удаления."));api.delete(row.optString("id"));mirror.removeAcknowledged(row.optString("id"));repo.cloudDeleted(account,row.optString("id"));deleted++;}
            mirror.apply(api.pull(mirror.cursor()));if(!mirror.hasSnapshot())throw new IOException(L.t("Сервер не вернул исходный снимок профилей. Локальные профили сохранены."));if(mirror.conflictCount()>0)throw new IOException(L.t("Разрешите конфликты облачных профилей; обе версии сохранены."));JSONArray remote=mirror.profiles();for(int i=0;i<remote.length();i++)if(remote.optJSONObject(i).optBoolean("dirty",false))throw new IOException(L.t("В локальной копии облака профилей есть локальные изменения. Отправьте или разрешите их перед синхронизацией."));applied=repo.mergeCloud(account,remote);
            JSONArray pending=repo.cloudPending(account);for(int i=0;i<pending.length();i++){JSONObject row=pending.optJSONObject(i),content=row.optJSONObject("content");long previous=row.optLong("updated_time",0);repo.reserveCloudUpload(account,row.optString("local_id"),row.optString("source_hash"));CloudProfileSync.Push result=api.push(row.optString("id"),content.optString("name"),content,previous==0?"":Long.toString(previous),false);if(result.isConflict()){mirror.recordConflict(row.optString("id"),result.conflict);throw new IOException(L.t("Конфликт отправки. Локальный профиль и ответ сервера сохранены; автоматическая перезапись не выполнялась."));}repo.cloudPushed(account,row.optString("local_id"),row.optString("source_hash"),result.updatedTime);mirror.upsertAcknowledged(row.optString("id"),content.optString("name"),content,result.updatedTime);uploaded++;}
        }
        prefs(c).edit().putLong("online_last_sync",System.currentTimeMillis()).putString("online_last_error","").apply();record(c,3,"preset-sync","completed");return L.t("Синхронизация: применено ")+applied+L.t(", отправлено ")+uploaded+L.t(", удалений ")+deleted+".";}}
    public static String connectionTest(Context c)throws IOException{NetworkPolicy.requireOnline(c);NetworkStore.Connection selected=NetworkStore.load(c).selected();if(selected!=null){NetworkPolicy.requireEndpoint(c,selected.endpoint);PrinterHostClient.HostInfo result=new PrinterHostClient(selected.endpoint).test(new NetworkHttp.Cancellation());return L.t("Связь с выбранным принтером подтверждена: ")+result.name+" · "+result.state;}NetworkPolicy.requireCloud(c);long begin=android.os.SystemClock.elapsedRealtime();NetworkHttp.Response r=NetworkHttp.request("GET",URI.create("https://api.github.com/repos/OrcaSlicer/OrcaSlicer"),java.util.Collections.emptyMap(),null,new NetworkHttp.Cancellation());r.requireSuccess();record(c,3,"network-test","https-success");return L.t("HTTPS к официальному репозиторию движка: HTTP ")+r.status+", "+(android.os.SystemClock.elapsedRealtime()-begin)+L.t(" мс. Выбранного принтера нет.");}
    /** Checks the official release channel; no desktop binary or incompatible preset pack is installed. */
    public static String checkUpdates(Context c)throws IOException{NetworkPolicy.requireCloud(c);NetworkHttp.Response r=NetworkHttp.request("GET",URI.create("https://api.github.com/repos/OrcaSlicer/OrcaSlicer/releases?per_page=30"),java.util.Collections.emptyMap(),null,new NetworkHttp.Cancellation(),8*1024*1024);r.requireSuccess();try{JSONObject chosen=OnlineRules.selectRelease(new JSONArray(r.text()),prefs(c).getBoolean("check_stable_update_only",true));if(chosen==null)throw new IOException(L.t("Нет релиза в выбранном канале."));String tag=chosen.optString("tag_name");prefs(c).edit().putString("online_release_tag",tag).putString("online_release_url",chosen.optString("html_url")).putLong("online_release_checked",System.currentTimeMillis()).apply();record(c,3,"release-check","completed");return L.t("Официальный релиз движка: ")+tag+(chosen.optBoolean("prerelease",false)?L.t(" · предварительный"):L.t(" · стабильный"))+L.t(". Это релиз настольного движка; Android APK автоматически не заменяется.");}catch(JSONException e){throw new IOException(L.t("Неверный ответ списка релизов."),e);}}
    public static int logLevel(Context c){String level=prefs(c).getString("log_severity_level","info");for(int i=0;i<LOG_LEVELS.length;i++)if(LOG_LEVELS[i].equals(level))return i;return 3;}
    /** Structured local diagnostics never include endpoints, credentials, account IDs or raw server bodies. */
    public static void record(Context c,int level,String event,String outcome){if(!OnlineRules.logEnabled(logLevel(c),level))return;try{File dir=new File(c.getFilesDir(),"diagnostics");synchronized(OnlinePreferences.class){if(!dir.isDirectory()&&!dir.mkdirs())return;File log=new File(dir,"events.jsonl");if(log.length()>1024*1024){File previous=new File(dir,"events.previous.jsonl");java.nio.file.Files.move(log.toPath(),previous.toPath(),java.nio.file.StandardCopyOption.REPLACE_EXISTING);}JSONObject row=new JSONObject().put("time",System.currentTimeMillis()).put("level",LOG_LEVELS[level]).put("event",event).put("outcome",outcome);try(java.io.FileOutputStream out=new java.io.FileOutputStream(log,true)){out.write((row.toString()+"\n").getBytes(StandardCharsets.UTF_8));}}}catch(Exception ignored){}}
    public static String diagnostics(Context c){SharedPreferences p=prefs(c);return "Android API "+android.os.Build.VERSION.SDK_INT+L.t("\nДвижок ")+PrinterProfileCatalog.UPSTREAM_REVISION+L.t("\nРегион: ")+REGIONS[regionIndex(c)]+L.t("\nОблако профилей: глобальный API api.orcaslicer.com\nСеть: ")+(NetworkPolicy.offline(c)?L.t("выключена"):p.getBoolean("stealth_mode",false)?L.t("только LAN"):L.t("включена"))+L.t("\nПоследняя синхронизация: ")+p.getLong("online_last_sync",0)+L.t("\nПоследняя проверка релиза: ")+p.getString("online_release_tag",L.t("не выполнялась"))+L.t("\nЖурнал Java: ")+LOG_LEVELS[logLevel(c)]+"\n"+bambuCapability();}
    public static String bambuCapability(){return L.t("Bambu network plug-in не установлен: в проекте нет Android-библиотеки и JNI-интерфейса Bambu. AMS, синхронизация филамента, проверка/разрешение abnormal storage, выбор версии и перезагрузка Bambu plug-in требуют этого провайдера. Встроенный HTTP-транспорт Kepler не выдаётся за Bambu plug-in.");}
    public static String reload(Context c)throws IOException{throw new IOException(bambuCapability());}
    public static void clearLocalSyncState(Context c)throws IOException{synchronized(SYNC_LOCK){try(PresetRepository repo=new PresetRepository(c)){repo.clearCloudAssociations();}JSONObject s=session(c);JSONObject user=s==null?null:s.optJSONObject("user");if(user!=null&&!user.optString("id").isEmpty())new CloudProfileStore(c,user.optString("id")).resetCursor();prefs(c).edit().remove("online_last_sync").remove("online_last_error").apply();}}
    public static String lastStatus(Context c){SharedPreferences p=prefs(c);String error=p.getString("online_last_error","");return error.isEmpty()?L.t("Последняя синхронизация: ")+p.getLong("online_last_sync",0):error;}
    /** Legacy mirror-editor uploads share the same request+commit lock as full sync. */
    public static String pushMirroredProfile(Context c,JSONObject supplied)throws IOException{synchronized(SYNC_LOCK){NetworkPolicy.requireCloud(c);try{JSONObject profile=new JSONObject(supplied.toString()),s=freshSession(c),user=s.optJSONObject("user");if(user==null)throw new IOException(L.t("Нет аккаунта."));CloudProfileStore mirror=new CloudProfileStore(c,user.optString("id"));String id=profile.getString("id"),name=profile.getString("name");JSONObject content=profile.getJSONObject("content"),current=null;JSONArray rows=mirror.profiles();for(int n=0;n<rows.length();n++){JSONObject row=rows.optJSONObject(n);if(row!=null&&id.equals(row.optString("id"))){current=row;break;}}long previous=profile.optLong("updated_time",0);if(current==null||current.optLong("updated_time",0)!=previous||!PresetJson.equal(current.optJSONObject("content"),content))throw new IOException(L.t("Профиль изменился после открытия. Обновите список."));CloudProfileSync.Push result=cloud(c,s,false).push(id,name,content,previous==0?"":Long.toString(previous),false);if(result.isConflict()){mirror.recordConflict(id,result.conflict);throw new IOException(L.t("Конфликт: обе версии сохранены. Автоматическая перезапись отключена."));}mirror.markPushed(id,content.toString(),result.updatedTime);return L.t("Профиль отправлен.");}catch(JSONException e){throw new IOException(L.t("Некорректный профиль."),e);}}}
    public static JSONArray conflictReviews(Context c)throws IOException{synchronized(SYNC_LOCK){JSONObject s=freshSession(c),user=s.optJSONObject("user");if(user==null)throw new IOException(L.t("Сначала войдите в облако профилей."));String account=user.optString("id");CloudProfileStore mirror=new CloudProfileStore(c,account);mirror.apply(cloud(c,s,false).pull(0));if(!mirror.hasSnapshot())throw new IOException(L.t("Нет полного снимка сервера."));try(PresetRepository repo=new PresetRepository(c)){return repo.cloudReviews(account,mirror.serverProfiles());}}}
    /** Choices are per reviewed profile; no unrelated source is overwritten. */
    public static String resolveConflict(Context c,JSONObject review,String choice,String duplicateName)throws IOException{synchronized(SYNC_LOCK){JSONObject s=freshSession(c),user=s.optJSONObject("user");if(user==null)throw new IOException(L.t("Сначала войдите в облако профилей."));String account=user.optString("id"),id=review.optString("id");CloudProfileStore mirror=new CloudProfileStore(c,account);try(PresetRepository repo=new PresetRepository(c)){
        repo.confirmCloudReview(account,review.optString("local_id"),review.optString("local_hash"));
        if("local".equals(choice)){JSONObject content=review.optJSONObject("upload_content");if(content==null)throw new IOException(L.t("Нет проверенной локальной версии."));long time=review.optLong("server_time",0);repo.reserveCloudUpload(account,review.optString("local_id"),review.optString("local_hash"));CloudProfileSync.Push pushed=cloud(c,s,false).push(id,content.optString("name"),content,time==0?"":Long.toString(time),false);if(pushed.isConflict()){mirror.recordConflict(id,pushed.conflict);throw new IOException(L.t("Сервер снова изменился. Откройте обновлённый конфликт; перезапись не выполнена."));}repo.cloudPushed(account,review.optString("local_id"),review.optString("local_hash"),pushed.updatedTime);mirror.upsertAcknowledged(id,content.optString("name"),content,pushed.updatedTime);return L.t("Проверенная локальная версия отправлена с проверкой ревизии сервера.");}
        if(!"remote".equals(choice)&&!"duplicate".equals(choice))throw new IOException(L.t("Неизвестный выбор конфликта."));String copy=repo.acceptCloudReview(account,review,"duplicate".equals(choice)?duplicateName:null);if(review.optBoolean("deleted",false))mirror.removeAcknowledged(id);else{JSONObject content=review.optJSONObject("server_source");mirror.upsertAcknowledged(id,content.optString("name"),content,review.optLong("server_time",0));}return copy.isEmpty()?L.t("Принята только проверенная серверная версия этого профиля."):L.t("Локальная версия сохранена отдельным профилем; для исходного принята серверная версия.");
    }}}
    private static String safeMessage(Throwable e){String m=e.getMessage();return m==null?e.getClass().getSimpleName():m;}
}
